#include "resources.h"

#include <algorithm>
#include <cstddef>

// The table generated by cmake/resources.cmake (resources_table.cpp).
struct EmbeddedResource {
    const char* name;
    const unsigned char* data;
    size_t size;
};
extern const EmbeddedResource kEmbeddedResources[];
extern const size_t kEmbeddedResourceCount;

static Resource to_resource(const EmbeddedResource& r) {
    return {r.name, std::string_view(reinterpret_cast<const char*>(r.data), r.size)};
}

std::optional<std::string_view> resource(std::string_view name) {
    for (size_t i = 0; i < kEmbeddedResourceCount; i++)
        if (name == kEmbeddedResources[i].name) return to_resource(kEmbeddedResources[i]).data;
    return std::nullopt;
}

std::vector<Resource> resources_with_prefix(std::string_view prefix) {
    std::vector<Resource> out;
    for (size_t i = 0; i < kEmbeddedResourceCount; i++)
        if (std::string_view(kEmbeddedResources[i].name).starts_with(prefix)) out.push_back(to_resource(kEmbeddedResources[i]));
    std::sort(out.begin(), out.end(), [](const Resource& a, const Resource& b) { return a.name < b.name; });
    return out;
}
